<nav class="account-nav"><?php foreach (['learning'=>['My learning','book'],'support'=>['Support desk','message'],'profile'=>['Profile','user'],'security'=>['Security','shield'],'wallet'=>['Wallet','wallet'],'orders'=>['Orders','box'],'favorites'=>['Bookmarks','bookmark'],'messages'=>['Messages','message'],'notifications'=>['Notifications','bell'],'tasks'=>['Task center','gift'],'cart'=>['Cart','box'],'creator'=>['Creator studio','chart'],'history'=>['Reading history','book'],'following'=>['Following feed','users']] as $r=>$v): if(in_array($r,['learning','support'],true)&&!$s->enabled($r==='learning'?'courses':'support')){continue;} if (isset(['creator'=>1,'history'=>1,'following'=>1][$r]) && !$s->enabled(['creator'=>'creator_income','history'=>'reading_history','following'=>'follows'][$r])) {continue;} if (in_array($r,['wallet','favorites','messages','cart','tasks'],true) && !$s->enabled($r)) {continue;} ?><a class="<?= ($route??'')===$r?'active':'' ?>" href="<?= e(url($r)) ?>"><?= icon($v[1]) ?><?= t($v[0]) ?></a><?php endforeach ?></nav>
